import{_ as l,a0 as u,w as r,s as p,ao as m,I as d,x as t,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 有問必答：如何使用yum來下載RPM包而不進行安裝 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何使用yum來下載RPM包而不進行安裝 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何使用yum來下載RPM包而不進行安裝 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何使用yum來下載RPM包而不進行安裝 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150122 Linux FAQs with Answers--How to use yum to download a RPM package without installing it","title":"Linux 有問必答：如何使用yum來下載RPM包而不進行安裝","tag":"201503","desc":""},"relativePath":"201503/20150122 Linux FAQs with Answers--How to use yum to download a RPM package without installing it.md","filePath":"[post].md"}'),s={name:"201503/20150122 Linux FAQs with Answers--How to use yum to download a RPM package without installing it.md"};function i(y,o,w,x,g,c){const e=u("Link");return r(),p("div",null,[o[11]||(o[11]=m(`<h1 id="linux-有問必答-如何使用yum來下載rpm包而不進行安裝" tabindex="-1">Linux 有問必答：如何使用yum來下載RPM包而不進行安裝 <a class="header-anchor" href="#linux-有問必答-如何使用yum來下載rpm包而不進行安裝" aria-label="Permalink to “Linux 有問必答：如何使用yum來下載RPM包而不進行安裝”">​</a></h1><blockquote><p><strong>問題</strong>:我想從Red Hat 的標準倉庫中下載一個RPM包，我能使用yum命令來下載一個RPM包但是不進行安裝嗎？</p></blockquote><p>yum是基於Red Hat的系統(如CentOS、Fedora、RHEl)上的默認包管理器。使用yum，你可以安裝或者更新一個RPM包，並且他會自動解決包依賴關係。但是如果你只想將一個RPM包下載到你的系統上該怎麼辦呢? 例如，你可能想要獲取一些RPM包在以後使用，或者將他們安裝在另外的機器上。</p><p>這裏説明了如何從yum倉庫上下載一個RPM包。</p><h3 id="方法一-yum" tabindex="-1">方法一:yum### <a class="header-anchor" href="#方法一-yum" aria-label="Permalink to “方法一:yum###”">​</a></h3><p>yum命令本身就可以用來下載一個RPM包，標準的yum命令提供了<code>--downloadonly(只下載)</code>的選項來達到這個目的。</p><pre><code>$ sudo yum install --downloadonly &lt;package-name&gt;
</code></pre><p>默認情況下，一個下載的RPM包會保存在下面的目錄中:</p><pre><code>/var/cache/yum/x86_64/[centos/fedora-version]/[repository]/packages
</code></pre><p>以上的[repository]表示下載包的來源倉庫的名稱(例如：base、fedora、updates)</p><p>如果你想要將一個包下載到一個指定的目錄(如/tmp)：</p><pre><code>$ sudo yum install --downloadonly --downloaddir=/tmp &lt;package-name&gt;
</code></pre><p>注意，如果下載的包包含了任何沒有滿足的依賴關係，yum將會把所有的依賴關係包下載，但是都不會被安裝。</p><p>另外一個重要的事情是，在CentOS/RHEL 6或更早期的版本中，你需要安裝一個單獨yum插件(名稱為 yum-plugin-downloadonly)才能使用<code>--downloadonly</code>命令選項：</p><pre><code>$ sudo yum install yum-plugin-downloadonly
</code></pre><p>如果沒有該插件，你會在使用yum時得到以下錯誤：</p><pre><code>Command line error: no such option: --downloadonly
</code></pre><p><img src="https://farm9.staticflickr.com/8627/15571201803_38390aae75_c.jpg" alt=""></p><h3 id="方法二-yumdownloader" tabindex="-1">方法二: Yumdownloader### <a class="header-anchor" href="#方法二-yumdownloader" aria-label="Permalink to “方法二: Yumdownloader###”">​</a></h3><p>另外一個下載RPM包的方法就是通過一個專門的包下載工具--yumdownloader。 這個工具是yum工具包(包含了用來進行yum包管理的幫助工具套件)的子集。</p><pre><code>$ sudo yum install yum-utils
</code></pre><p>下載一個RPM包：</p><pre><code>$ sudo yumdownloader &lt;package-name&gt;
</code></pre><p>下載的包會被保存在當前目錄中。你需要使用root權限，因為yumdownloader會在下載過程中更新包索引文件。與yum命令不同的是，任何依賴包不會被下載。</p><hr>`,25)),d("p",null,[o[1]||(o[1]=t("via: ",-1)),a(e,{href:"http://ask.xmodulo.com/yum-download-rpm-package.html"},{default:n(()=>[...o[0]||(o[0]=[t("http://ask.xmodulo.com/yum-download-rpm-package.html",-1)])]),_:1})]),d("p",null,[o[4]||(o[4]=t("譯者：",-1)),a(e,{href:"https://github.com/theo-l"},{default:n(()=>[...o[2]||(o[2]=[t("theo-l",-1)])]),_:1}),o[5]||(o[5]=t(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...o[3]||(o[3]=[t("wxy",-1)])]),_:1})]),d("p",null,[o[8]||(o[8]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[6]||(o[6]=[t("LCTT",-1)])]),_:1}),o[9]||(o[9]=t(" 原創翻譯，",-1)),a(e,{href:"http://linux.cn/"},{default:n(()=>[...o[7]||(o[7]=[t("Linux中國",-1)])]),_:1}),o[10]||(o[10]=t(" 榮譽推出",-1))])])}const R=l(s,[["render",i]]);export{f as __pageData,R as default};
